function configure(){zoom=Number(document.querySelector('#zoom').value);const dirs=document.querySelector('#directions').value.split(',').map(Number);cards.forEach(card=>{card.direction=dirs[card.row];card.caption.textContent=(card.row?'Trasera':'Delantera')+' · '+(card.variant?'Borde ajustado':'Original')+' · posición '+card.direction;card.canvas.width=Math.max(...variants.flatMap(v=>v.images.map(i=>i.naturalWidth||1)))*zoom+40;card.canvas.height=Math.max(...variants.flatMap(v=>v.images.map(i=>i.naturalHeight||1)))*zoom+60})}
document.querySelector('#pause').onclick=()=>{running=!running;document.querySelector('#pause').textContent=running?'Pausar':'Reanudar'};document.querySelector('#zoom').onchange=configure;document.querySelector('#directions').onchange=configure;document.querySelector('#background').onchange=e=>{document.body.style.setProperty('--base',e.target.value==='dark'?'#334155':'#fff');document.body.style.setProperty('--tile',e.target.value==='dark'?'#283446':'#eee')};
function draw(now){if(running)elapsed+=now-last;last=now;cards.forEach(card=>{const v=variants[card.variant],action=v.directions[card.direction],frame=action.frames[Math.floor(elapsed/action.ms)%action.frames.length],img=v.images[frame[0]],c=card.ctx;c.clearRect(0,0,card.canvas.width,card.canvas.height);if(!img.complete||!img.naturalWidth)return;c.save();c.translate(card.canvas.width/2+frame[2]*zoom,card.canvas.height-20+frame[3]*zoom);if(frame[1])c.scale(-1,1);c.imageSmoothingEnabled=false;c.drawImage(img,-Math.floor(img.width/2)*zoom,-Math.floor(img.height/2)*zoom,img.width*zoom,img.height*zoom);c.restore()});requestAnimationFrame(draw)}Promise.all(variants.flatMap(v=>v.images.map(img=>img.decode()))).then(()=>{configure();requestAnimationFrame(draw)});